# IMAGENS OFICIAIS DA REGULARIZE EMBUTIDAS (EXTRAÍDAS DA PLANILHA ORIGINAL)
# ============================================================================
MARCA_DAGUA_REGULARIZE_B64 = ""
LOGO_REGULARIZE_PB_B64 = ""

# Margens confortáveis para impressão A4 sem cortar bordas e com ótimo respiro
MARGEM_H = 1.4 * cm
MARGEM_V = 1.3 * cm
LARGURA_UTIL = A4[0] - (2 * MARGEM_H)   # ~18,20 cm
ALTURA_UTIL = A4[1] - (2 * MARGEM_V)    # ~27,10 cm


# ============================================================================
# FUNÇÕES DE FORMATAÇÃO PT-BR (CAMPO VAZIO = 100% EM BRANCO, SEM ZEROS/TRAÇOS)
# ============================================================================
def parse_moeda_br(valor):
    """
    Converte qualquer entrada monetária brasileira ou numérica em float (ou None se vazio/zero).
    Exemplos aceitos: '10.000,00', '10000', '10.000', '10000,5', 'R$ 2.500,75', 10000.0.
    Retorna None para vazio, None ou 0 (nunca gera 0,00 indesejado).
    """
    if valor is None:
        return None
    if isinstance(valor, (int, float)):
        v = float(valor)
        return round(v, 2) if abs(v) >= 0.005 else None

    s = str(valor).strip()
    if not s:
        return None
    # Remove 'R$', espaços e caracteres não numéricos (mantendo dígitos, ponto, vírgula e sinal)
    s = s.replace("R$", "").replace("r$", "").strip()
    s = "".join(ch for ch in s if ch.isdigit() or ch in ".,-")
    if not s or s in ("-", ".", ",", "-.", "-,"):
        return None

    if "," in s and "." in s:
        if s.rfind(",") > s.rfind("."):
            # Padrão brasileiro: 10.000,50
            s = s.replace(".", "").replace(",", ".")
        else:
            # Padrão americano: 10,000.50
            s = s.replace(",", "")
    elif "," in s:
        # Apenas vírgula: 10000,50 ou 2,45
        if s.count(",") == 1:
            s = s.replace(",", ".")
        else:
            partes = s.split(",")
            if len(partes[-1]) in (1, 2):
                s = "".join(partes[:-1]) + "." + partes[-1]
            else:
                s = "".join(partes)
    elif "." in s:
        # Apenas ponto: diferencia milhar brasileiro (10.000) de decimal (10000.50)
        if s.count(".") > 1:
            partes = s.split(".")
            if len(partes[-1]) in (1, 2):
                s = "".join(partes[:-1]) + "." + partes[-1]
            else:
                s = "".join(partes)
        else:
            antes, depois = s.split(".", 1)
            if len(depois) == 3 and depois.isdigit():
                # Ex.: "10.000" -> 10000 (milhar brasileiro)
                s = antes + depois

    try:
        v = float(s)
    except ValueError:
        return None
    return round(v, 2) if abs(v) >= 0.005 else None


def fmt_input_moeda_br(valor):
    """Formata valor monetário no padrão brasileiro para campos de tela: ex. '10.000,00'. Vazio/zero -> ''."""
    v = parse_moeda_br(valor)
    if v is None:
        return ""
    sinal = "-" if v < 0 else ""
    texto = f"{abs(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"{sinal}{texto}"


def fmt_moeda(valor, vazio_se_zero=True):
    """
    Formata 10000 como 'R$ 10.000,00'.
    Se o valor for vazio, None ou 0 (com vazio_se_zero=True), retorna '' (em branco).
    """
    v = parse_moeda_br(valor)
    if v is None:
        return "" if vazio_se_zero else "R$ 0,00"
    sinal = "-" if v < 0 else ""
    texto = f"{abs(v):,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")
    return f"{sinal}R$ {texto}"


def fmt_valor_sem_rs(valor):
    """Formata 10000 como '10.000,00' (sem 'R$'). Se vazio ou zero, retorna ''."""
    return fmt_input_moeda_br(valor)


def fmt_pct_br(valor_pct):
    """Formata porcentagem no padrão brasileiro com vírgula (ex.: 0.5 -> '0,50%')."""
    try:
        v = float(valor_pct or 0)
    except (TypeError, ValueError):
        return ""
    if abs(v) < 1e-6:
        return ""
    return f"{v:.2f}%".replace(".", ",")


def fmt_num(valor):
    """
    Formata número no padrão brasileiro.
    Se for vazio, None ou 0, retorna '' (em branco, sem '0' nem traço).
    """
    if valor is None or str(valor).strip() == "":
        return ""
    try:
        v = float(valor)
    except (TypeError, ValueError):
        return str(valor).strip()
    if abs(v) < 1e-9:
        return ""
    if v.is_integer():
        return f"{int(v):,}".replace(",", ".")
    return f"{v:,.2f}".replace(",", "X").replace(".", ",").replace("X", ".")


def fmt_doc(cpf_cnpj):
    """Formata CPF (000.000.000-00) ou CNPJ (00.000.000/0000-00). Vazio -> ''."""
    if not cpf_cnpj:
        return ""
    d = "".join(ch for ch in str(cpf_cnpj) if ch.isdigit())
    if not d:
        return ""
    if len(d) == 11:
        return f"{d[:3]}.{d[3:6]}.{d[6:9]}-{d[9:]}"
    if len(d) == 14:
        return f"{d[:2]}.{d[2:5]}.{d[5:8]}/{d[8:12]}-{d[12:]}"
    return str(cpf_cnpj).strip()


def fmt_cep(cep):
    """Formata CEP como 00000-000. Vazio -> ''."""
    if not cep:
        return ""
    d = "".join(ch for ch in str(cep) if ch.isdigit())
    if not d:
        return ""
    if len(d) == 8:
        return f"{d[:5]}-{d[5:]}"
    return str(cep).strip()


def fmt_data_extenso(dt=None):
    """Retorna data por extenso em português ou '' se não preenchida."""
    if not dt:
        return ""
    if isinstance(dt, str):
        s = dt.strip()
        if not s:
            return ""
        try:
            dt = datetime.strptime(s[:10], "%Y-%m-%d").date()
        except ValueError:
            return s
    meses = [
        "janeiro", "fevereiro", "março", "abril", "maio", "junho",
        "julho", "agosto", "setembro", "outubro", "novembro", "dezembro",
    ]
    return f"{dt.day:02d} de {meses[dt.month - 1]} de {dt.year}"


def fmt_data_br(dt=None):
    """Retorna data como '25/11/2026' ou '' se não preenchida."""
    if not dt:
        return ""
    if isinstance(dt, str):
        s = dt.strip()
        if not s:
            return ""
        try:
            dt = datetime.strptime(s[:10], "%Y-%m-%d").date()
        except ValueError:
            return s
    return dt.strftime("%d/%m/%Y")


def safe(texto):
    """Protege caracteres especiais para o motor PDF. None -> ''."""
    if texto is None:
        return ""
    return escape(str(texto).strip())


# ============================================================================
# MARCA D'ÁGUA OFICIAL DA REGULARIZE (EM TODAS AS FOLHAS IMPRESSAS)
# ============================================================================
def desenhar_marca_dagua(canvas, doc):
    """Desenha a marca d'água oficial da Regularize centralizada no fundo de cada folha."""
    canvas.saveState()
    largura_pag, altura_pag = A4
    wm_bytes = base64.b64decode(MARCA_DAGUA_REGULARIZE_B64)
    img_reader = ImageReader(io.BytesIO(wm_bytes))

    wm_w = 14.8 * cm
    wm_h = 11.8 * cm
    x = (largura_pag - wm_w) / 2.0
    y = (altura_pag - wm_h) / 2.0
    canvas.drawImage(
        img_reader, x, y, width=wm_w, height=wm_h,
        preserveAspectRatio=True, anchor="c",
    )
    canvas.restoreState()


