def doc_galpao_graos(d, est):
    g_cab = bloco_cabecalho_planilha("GALPÃO PARA ARMAZENAGEM DE GRÃOS", est, "DECLARAÇÃO DE FINALIDADE E RESPONSABILIDADE")

    cid_txt = safe(d.get("cidade"))
